SELECT COALESCE(SUM(id.qty), 0)
FROM inbound_detail id
JOIN inbound i ON i.inbound_id = id.inbound_id
WHERE i.account_id = #{accountId}
AND id.foreign_product_id = #{foreignProductId}

mapper.update:
UPDATE inbound_detail
SET current_qty = current_qty - #{qty}
WHERE inbound_detail_id = #{inboundDetailId} AND current_qty >= #{qty}

mapper.select:
SELECT id.inbound_id AS inboundId, id.inbound_detail_id AS inboundDetailId, id.source_broker AS sourceBroker, id.qty AS qty, id.current_qty AS currentQty, id.recorded_at AS recordedAt, id.account_type AS accountType, id.purchase_date AS purchaseDate, id.purchase_price AS purchasePrice, id.purchase_currency AS purchaseCurrency, id.purchase_fx_rate AS purchaseFxRate FROM inbound_detail id WHERE id.inbound_id IN
#{inboundId}
ORDER BY id.inbound_id, id.purchase_date ASC

SELECT a.account_id AS accountId, a.account_no AS accountNo, c.name AS customerName, COUNT(*) AS inboundCount, MAX(i.processed_at) AS lastProcessedAt FROM inbound i JOIN account a ON a.account_id = i.account_id JOIN customer c ON c.customer_id = a.customer_id
(c.name LIKE CONCAT('%', #{keyword}, '%') OR a.account_no LIKE CONCAT('%', #{keyword}, '%'))
GROUP BY a.account_id, a.account_no, c.name ORDER BY MAX(i.processed_at) DESC LIMIT #{size} OFFSET #{offset}

