AND id.registrable_stock_id = #{registrableStockId}

SELECT COUNT(*) > 0
FROM inbound_detail id
JOIN inbound i ON i.inbound_id = id.inbound_id
WHERE i.account_id = #{accountId}
AND id.foreign_product_id = #{foreignProductId}
AND id.source_general_account_id = #{sourceGeneralAccountId}
AND id.registrable_stock_id IS NULL

SELECT inbound_id, account_id, requested_qty, current_holding_at_request, approved_qty, processed_at
FROM inbound
WHERE inbound_id = #{inboundId} AND account_id = #{accountId}

